if(demoTick>=3){const idx=Math.min(model.paragraphs.length-1,Math.floor((demoTick-3)/3.4));if(idx!==active||demoTick===3){setActive(idx);$$('.paragraph')[idx].scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}const rect=$$('.paragraph')[idx].getBoundingClientRect();moveDot(rect.left+Math.min(rect.width*.6,280),rect.top+rect.height*.45);}
