async function detectServer(){if(extension||!['localhost','127.0.0.1','[::1]'].includes(location.hostname))return;try{const r=await fetch('/api/status',{signal:AbortSignal.timeout(2000)});const data=await r.json();cloudConfigured=data.configured===true;if(cloudConfigured){$('#cloud-row').hidden=false;$('#engine-note').textContent='Local by default. Jev sends the focused paragraph and reading goal to TypeSafe when enabled.';}}catch{/* The static demo stays fully local. */}}
$('#cloud-toggle').addEventListener('change',e=>{cloudEnabled=e.target.checked;if(rankController)rankController.abort();requestGeneration++;if(cloudEnabled){toast('Jev enabled: the focused paragraph and goal will be sent to TypeSafe.');requestJev();}else{render(false);toast('Back to local sentence scoring.');}setMode(mode);});
async function requestJev(){if(!cloudConfigured||!cloudEnabled||paused)return;const p=model.paragraphs[active];if(!p||p.sentences.length<2)return;if(rankController)rankController.abort();rankController=new AbortController();const gen=++requestGeneration;const originalIndex=active;$('#selection-reason').textContent='Asking Jev to choose an original sentence…';try{const r=await fetch('/api/rank',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({paragraphId:p.id,goal,topic,candidates:p.sentences.map(s=>({id:s.id,text:s.text}))}),signal:rankController.signal});const data=await r.json();if(!r.ok)throw Error(data.error||'Provider unavailable');if(gen!==requestGeneration||originalIndex!==active||!cloudEnabled)return;const found=p.sentences.find(s=>s.id===data.sentenceId);if(data.provider!=='jev'||!found)throw Error('Invalid selection');p.pick={...found,reason:'Jev selected this exact sentence. This is relevance, not factual verification.'};$$('.paragraph')[active].querySelectorAll('.sentence').forEach(el=>el.classList.toggle('picked',el.dataset.sentence===found.id));updateCard();}catch(e){if(e.name==='AbortError'||gen!==requestGeneration)return;$('#selection-reason').textContent='Jev unavailable or rate limited. Showing the local selection.';}}
async function importFromExtension(){if(!extension||!globalThis.chrome?.storage?.session)return;const key=new URLSearchParams(location.hash.slice(1)).get('import');if(!key||!/^skim-import-[a-zA-Z0-9-]{1,100}$/.test(key))return;try{const data=(await chrome.storage.session.get(key))[key];await chrome.storage.session.remove(key);history.replaceState(null,'',location.pathname);if(!data||typeof data.text!=='string')return;custom={title:typeof data.title==='string'?data.title.slice(0,100):'Imported page',source:'IMPORTED FROM YOUR TAB · LOCAL COPY',question:null,text:data.text.slice(0,24000)};sample='own';render();toast('Page imported. The original page is unchanged.');}catch{toast('The import expired. Open the extension on your page and try again.');}}
